import{_ as s,o as e,c as n,a6 as t}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"Advanced Generics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced-generics.md","filePath":"guide/advanced-generics.md","lastUpdated":1781686130000}'),i={name:"guide/advanced-generics.md"};function l(p,a,r,c,d,o){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="advanced-generics" tabindex="-1">Advanced Generics <a class="header-anchor" href="#advanced-generics" aria-label="Permalink to “Advanced Generics”">​</a></h1><p>This chapter covers NG&#39;s more advanced generic programming features: higher-kinded types, type specialization, enhanced tuples, fold expressions, and the <code>delete</code> mechanism.</p><h2 id="higher-kinded-generics-hkt" tabindex="-1">Higher-Kinded Generics (HKT) <a class="header-anchor" href="#higher-kinded-generics-hkt" aria-label="Permalink to “Higher-Kinded Generics (HKT)”">​</a></h2><p>Higher-kinded generics allow abstraction over <strong>type constructors</strong> — types that take type parameters.</p><h3 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h3><p>Without HKT, you need separate functions for <code>Box&lt;i32&gt;</code>, <code>Option&lt;string&gt;</code>, etc. With HKT, you can write one function over any container type.</p><h3 id="hkt-parameters" tabindex="-1">HKT Parameters <a class="header-anchor" href="#hkt-parameters" aria-label="Permalink to “HKT Parameters”">​</a></h3><p>Use <code>F&lt;_&gt;</code> syntax to declare a type constructor parameter:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Box&lt;T&gt; {</span></span>
<span class="line"><span>    value: T;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun accept&lt;F&lt;_&gt;, T&gt;(value: ref&lt;F&lt;T&gt;&gt;) -&gt; unit {</span></span>
<span class="line"><span>    print(&quot;accepted higher-kinded value&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val box = new Box&lt;i32&gt; { value: 42 };</span></span>
<span class="line"><span>accept&lt;Box, i32&gt;(box);   // explicit</span></span>
<span class="line"><span>accept(box);             // inferred</span></span></code></pre></div><h3 id="hkt-kind-parameters" tabindex="-1">HKT Kind Parameters <a class="header-anchor" href="#hkt-kind-parameters" aria-label="Permalink to “HKT Kind Parameters”">​</a></h3><p>The <code>_</code> in <code>F&lt;_&gt;</code> indicates a type constructor expecting exactly one type argument. NG supports:</p><table tabindex="0"><thead><tr><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>F&lt;_&gt;</code></td><td>Unary type constructor (e.g., <code>Box&lt;T&gt;</code>, <code>Option&lt;T&gt;</code>)</td></tr><tr><td><code>F&lt;_, _&gt;</code></td><td>Binary type constructor (e.g., <code>Result&lt;T, E&gt;</code>)</td></tr><tr><td><code>F&lt;..._&gt;</code></td><td>Variadic kind placeholder</td></tr></tbody></table><h3 id="variadic-hkt" tabindex="-1">Variadic HKT <a class="header-anchor" href="#variadic-hkt" aria-label="Permalink to “Variadic HKT”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun variadic&lt;F&lt;..._&gt;, T...&gt;(value: ref&lt;F&lt;T...&gt;&gt;) -&gt; unit {</span></span>
<span class="line"><span>    print(&quot;variadic HKT&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="hkt-trait-parameters" tabindex="-1">HKT Trait Parameters <a class="header-anchor" href="#hkt-trait-parameters" aria-label="Permalink to “HKT Trait Parameters”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trait Mappable&lt;F&lt;_&gt;&gt; {</span></span>
<span class="line"><span>    fun map&lt;T, U&gt;(self: ref&lt;F&lt;T&gt;&gt;, f: (T) -&gt; U) -&gt; F&lt;U&gt;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="hkt-constraints" tabindex="-1">HKT Constraints <a class="header-anchor" href="#hkt-constraints" aria-label="Permalink to “HKT Constraints”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun process&lt;F&lt;_&gt;, T&gt;(container: ref&lt;F&lt;T&gt;&gt;) where Mappable&lt;F&gt; {</span></span>
<span class="line"><span>    // container guaranteed to have a map method</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="type-specialization" tabindex="-1">Type Specialization <a class="header-anchor" href="#type-specialization" aria-label="Permalink to “Type Specialization”">​</a></h2><p>Type specialization allows providing different implementations based on concrete type patterns.</p><h3 id="partial-specialization" tabindex="-1">Partial Specialization <a class="header-anchor" href="#partial-specialization" aria-label="Permalink to “Partial Specialization”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Base definition</span></span>
<span class="line"><span>type Wrapper&lt;T&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Specialization for i32</span></span>
<span class="line"><span>type Wrapper&lt;i32&gt; {</span></span>
<span class="line"><span>    value: i32;</span></span>
<span class="line"><span>    fun double(self: ref&lt;Self&gt;) -&gt; i32 =&gt; self.value * 2;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Specialization for string</span></span>
<span class="line"><span>type Wrapper&lt;string&gt; {</span></span>
<span class="line"><span>    value: string;</span></span>
<span class="line"><span>    fun shout(self: ref&lt;Self&gt;) -&gt; string =&gt; self.value + &quot;!!!&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="where-predicates-in-specialization" tabindex="-1">Where Predicates in Specialization <a class="header-anchor" href="#where-predicates-in-specialization" aria-label="Permalink to “Where Predicates in Specialization”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Handler&lt;T&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Handler&lt;T&gt; where is_numeric&lt;T&gt;() {</span></span>
<span class="line"><span>    fun handle(self: ref&lt;Self&gt;, value: T) =&gt; print(&quot;numeric:&quot;, value);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Handler&lt;string&gt; {</span></span>
<span class="line"><span>    fun handle(self: ref&lt;Self&gt;, value: string) =&gt; print(&quot;string:&quot;, value);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="most-specific-pattern-matching" tabindex="-1">Most Specific Pattern Matching <a class="header-anchor" href="#most-specific-pattern-matching" aria-label="Permalink to “Most Specific Pattern Matching”">​</a></h3><p>The type checker selects the <strong>most specific</strong> matching pattern. If multiple patterns match, the most specific one wins:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Generic</span></span>
<span class="line"><span>fun describe&lt;T&gt;(value: T) -&gt; string =&gt; &quot;unknown&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// More specific: references</span></span>
<span class="line"><span>fun describe&lt;T&gt;(value: ref&lt;T&gt;) -&gt; string =&gt; &quot;reference&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Most specific: string</span></span>
<span class="line"><span>fun describe(value: string) -&gt; string =&gt; &quot;exact string&quot;;</span></span></code></pre></div><h3 id="abstract-type-aliases" tabindex="-1">Abstract Type Aliases <a class="header-anchor" href="#abstract-type-aliases" aria-label="Permalink to “Abstract Type Aliases”">​</a></h3><p>Declare a type alias without a body — implementations must specialize it:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type ResultType&lt;T&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type ResultType&lt;i32&gt; { value: i32; }</span></span>
<span class="line"><span>type ResultType&lt;string&gt; { value: string; }</span></span></code></pre></div><h2 id="enhanced-tuple-types" tabindex="-1">Enhanced Tuple Types <a class="header-anchor" href="#enhanced-tuple-types" aria-label="Permalink to “Enhanced Tuple Types”">​</a></h2><p>NG&#39;s tuple system includes type-level operations.</p><h3 id="tuple-type-predicates" tabindex="-1">Tuple Type Predicates <a class="header-anchor" href="#tuple-type-predicates" aria-label="Permalink to “Tuple Type Predicates”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.tuple;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const if (is_tuple&lt;tuple&gt;) {</span></span>
<span class="line"><span>    print(&quot;tuple type recognized&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const if (tuple_size&lt;tuple&gt; == 3) {</span></span>
<span class="line"><span>    print(&quot;tuple has 3 elements&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="tuple-element-projection" tabindex="-1">Tuple Element Projection <a class="header-anchor" href="#tuple-element-projection" aria-label="Permalink to “Tuple Element Projection”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.tuple;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val t = (1, &quot;hello&quot;, true);</span></span>
<span class="line"><span>type Second = tuple_element&lt;typeof(t), 1&gt;;</span></span>
<span class="line"><span>// Second is string</span></span></code></pre></div><h3 id="tuple-concatenation" tabindex="-1">Tuple Concatenation <a class="header-anchor" href="#tuple-concatenation" aria-label="Permalink to “Tuple Concatenation”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.tuple;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Extended = tuple_concat&lt;(i32, string), (bool, f64)&gt;;</span></span>
<span class="line"><span>// Extended is (i32, string, bool, f64)</span></span></code></pre></div><h3 id="spread-expansion" tabindex="-1">Spread Expansion <a class="header-anchor" href="#spread-expansion" aria-label="Permalink to “Spread Expansion”">​</a></h3><p>Enhanced tuples support spread expansion in function calls:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun sum(a: i32, b: i32, c: i32) -&gt; i32 =&gt; a + b + c;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val args = (1, 2, 3);</span></span>
<span class="line"><span>val result = sum(...args);   // expands to sum(1, 2, 3)</span></span></code></pre></div><h3 id="pack-to-tuple-return" tabindex="-1">Pack-to-Tuple Return <a class="header-anchor" href="#pack-to-tuple-return" aria-label="Permalink to “Pack-to-Tuple Return”">​</a></h3><p>Parameter packs can be returned as tuples:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun packToTuple&lt;T...&gt;(args: T...) -&gt; (T...) =&gt; args;</span></span></code></pre></div><h2 id="fold-expressions" tabindex="-1">Fold Expressions <a class="header-anchor" href="#fold-expressions" aria-label="Permalink to “Fold Expressions”">​</a></h2><p>Fold expressions allow reducing a parameter pack with a binary operator:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun sumAll&lt;T...&gt;(args: T...) -&gt; i32 {</span></span>
<span class="line"><span>    return (... + args);  // fold left: ((a + b) + c) + ...</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(sumAll(1, 2, 3, 4));  // 10</span></span></code></pre></div><h3 id="supported-fold-operators" tabindex="-1">Supported Fold Operators <a class="header-anchor" href="#supported-fold-operators" aria-label="Permalink to “Supported Fold Operators”">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th></tr></thead><tbody><tr><td><code>... + args</code></td><td>Sum</td></tr><tr><td><code>... * args</code></td><td>Product</td></tr><tr><td><code>... &amp;&amp; args</code></td><td>Logical AND</td></tr><tr><td><code>... || args</code></td><td>Logical OR</td></tr></tbody></table><h2 id="delete-mechanism" tabindex="-1">Delete Mechanism <a class="header-anchor" href="#delete-mechanism" aria-label="Permalink to “Delete Mechanism”">​</a></h2><p>The <code>delete</code> keyword removes specific generic instantiations, preventing certain types from being used.</p><h3 id="deleted-functions" tabindex="-1">Deleted Functions <a class="header-anchor" href="#deleted-functions" aria-label="Permalink to “Deleted Functions”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Accept all types</span></span>
<span class="line"><span>fun process&lt;T&gt;(value: T) -&gt; string =&gt; &quot;default&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Delete string instantiation</span></span>
<span class="line"><span>delete fun process&lt;string&gt;(value: string);</span></span></code></pre></div><h3 id="deleted-type-aliases" tabindex="-1">Deleted Type Aliases <a class="header-anchor" href="#deleted-type-aliases" aria-label="Permalink to “Deleted Type Aliases”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Container&lt;T&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>delete type Container&lt;ref&lt;T&gt;&gt;;  // Reject references</span></span></code></pre></div><h3 id="priority-rule" tabindex="-1">Priority Rule <a class="header-anchor" href="#priority-rule" aria-label="Permalink to “Priority Rule”">​</a></h3><p>More specific deletions take priority over less specific ones. A deleted specialization can coexist with a valid fallback:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun handle&lt;T&gt;(value: T) -&gt; string =&gt; &quot;fallback&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// More specific deletion beats fallback</span></span>
<span class="line"><span>delete fun handle&lt;ref&lt;T&gt;&gt;(value: ref&lt;T&gt;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>handle(42);          // &quot;fallback&quot; (OK)</span></span>
<span class="line"><span>// handle(ref 42);</span><span>   // COMPILE ERROR: deleted</span></span></code></pre></div><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./standard-library">Standard Library</a> to explore NG&#39;s built-in library.</p><blockquote><p><strong>Try it:</strong> <code>example/48.higher_kinded_generics.ng</code> — HKT basics <strong>Try it:</strong> <code>example/49.variadic_hkt_kind.ng</code> — Variadic HKT <strong>Try it:</strong> <code>example/44.type_specialization.ng</code> — Type specialization <strong>Try it:</strong> <code>example/43.const_specialization.ng</code> — Const specialization <strong>Try it:</strong> <code>example/54.enhanced_tuple_types.ng</code> — Enhanced tuples <strong>Try it:</strong> <code>example/58.fold_expressions.ng</code> — Fold expressions</p></blockquote>`,61)])])}const u=s(i,[["render",l]]);export{g as __pageData,u as default};
